import * as array from "std/array"
import * as simd from "std/simd"
import * as codec from "ink/codec"
import * as changes from "ink/changes"
import * as queue from "ink/task_queue"

// Complete decoder, including framing, finite/integer checks and padding.
const unpack = fn (capacity: U32) (payload: Array F32) -> Maybe (Array U32) => do:
  if payload.length < 2 || payload.length % 2 != 0:
    return #Nothing
  for group in 0 .. payload.length / 4:
    let values = simd.load (group * 4) payload
    let valid = simd.u32_and (simd.f32_ge values (simd.f32_splat 0.0)) (simd.f32_le values (simd.f32_splat 65535.0))
    valid := simd.u32_and self (simd.f32_eq values (simd.f32_floor values))
    if simd.any_true (simd.u32_not valid):
      return #Nothing
  for at in payload.length / 4 * 4 .. payload.length:
    let value = payload[at]
    if Bool.not (is_finite value) || value < 0.0 || value > 65535.0 || floor value != value:
      return #Nothing
  let count = F32.to_u32 payload[0] | (F32.to_u32 payload[1] << 16)
  let size = (payload.length - 2) / 2
  if count > size || (capacity == 0 && count != size) || (capacity != 0 && size != capacity):
    return #Nothing
  for i in 2 + count * 2 .. payload.length:
    if payload[i] != 0.0:
      return #Nothing
  let result = array.fill count 0
  for group in 0 .. count / 4:
    let a = simd.load (2 + group * 8) payload
    let b = simd.load (6 + group * 8) payload
    let low = simd.to_u32 (simd.f32_shuffle (0, 2, 4, 6) a b)
    let high = simd.to_u32 (simd.f32_shuffle (1, 3, 5, 7) a b)
    result := simd.store (group * 4) (simd.u32_or low (simd.u32_shl 16 high)) self
  for i in count / 4 * 4 .. count:
    result[i] := F32.to_u32 payload[2 + i * 2] | (F32.to_u32 payload[3 + i * 2] << 16)
  return #Some result
const decode_run = fn decode (count: U32) => do:
  let packet = codec.pack (count + 7) (array.generate count (fn i => i * 2654435761))
  return Maybe.unwrap_or #[] (decode (count + 7) packet)
entry const decode_before = decode_run codec.unpack
entry const decode_after = decode_run unpack
entry const decode_bad_before = fn (packet: Array F32) => Maybe.unwrap_or #[123456789] (codec.unpack 0 packet)
entry const decode_bad_after = fn (packet: Array F32) => Maybe.unwrap_or #[123456789] (unpack 0 packet)

// Sorted unique inputs, as used internally by normalized Changes.
const without = fn (values: Array U32) (excluded: Array U32) => do:
  if excluded.length == 0:
    return values
  let result = array.fill values.length 0
  let count = 0
  let next = 0
  for value in values:
    for next .. excluded.length:
      if excluded[next] >= value:
        break
      next := self + 1
    if next == excluded.length || excluded[next] != value:
      result[count] := value
      count := self + 1
  return array.slice 0 count result
const change_run = fn subtract (count: U32) => do:
  let values = array.generate count (fn i => i * 2)
  let excluded = array.generate count (fn i => i * 3)
  let result = #[]
  for 0 .. 16:
    result := subtract values excluded
  return result
entry const changes_before = change_run changes.without
entry const changes_after = change_run without

const encode = fn encode_request encode_value encode_local (q: queue.Queue [request, value, local]) => do:
  let chunks = array.generate q.jobs.length (fn index => do:
    let job = q.jobs[index]
    let request = encode_request job.request
    let local = encode_local job.continuation
    let (tag, tick, value) = case job.state of
      #queue.Pending => (0, 0, #[])
      #queue.Ready {tick, outcome} => case outcome of
        #queue.Value value => (1, tick, encode_value value)
        #queue.Failed reason => (2, tick, #[reason])
        #queue.Cancelled reason => (3, tick, #[reason])
    return array.flatten #[#[job.ticket.sequence, job.submitted, job.earliest, tag, tick, request.length, local.length, value.length], request, local, value])
  return array.concat #[1, q.epoch, q.next, q.capacity, if q.open then 1 else 0, q.tick, q.jobs.length] (array.flatten chunks)
const queue_run = fn serialize (count: U32) => do:
  let q: queue.Queue [U32, U32, U32] = queue.make 1 count #False
  q.next := count + 1
  q.tick := 1
  q.jobs := array.generate count (fn i => #queue.Job {ticket: #queue.Ticket {epoch: 1, sequence: i + 1}, submitted: 0, earliest: 1,
    request: i, continuation: i * 3, state: case i % 4 of
      0 => #queue.Pending
      1 => #queue.Ready {tick: 1, outcome: #queue.Value (i * 5)}
      2 => #queue.Ready {tick: 1, outcome: #queue.Failed (i * 7)}
      _ => #queue.Ready {tick: 1, outcome: #queue.Cancelled (i * 11)}})
  return serialize (fn i => #[i, i + 1]) (fn i => #[i, i + 1, i + 2]) (fn i => #[i]) q
entry const queue_before = queue_run queue.encode
entry const queue_after = queue_run encode

prototype.rustHarness:
use ink_tools::{Fixture, compiled};
use serde_json::json;
use std::time::Instant;
fn main() {
    let module = compiled(".cache/next-ink-review/probe.blot", &[]);
    let mut f = Fixture::from_module(&module);
    for count in [0usize, 1, 3, 4, 5, 65, 257] {
        for stem in ["decode", "changes", "queue"] {
            assert_eq!(f.call(&format!("{stem}_before"), count).unwrap(), f.call(&format!("{stem}_after"), count).unwrap());
        }
    }
    let packet = vec![5., 0., 0., 0., 65535., 65535., 1., 2., 0., 32768., 65535., 0.];
    for end in 0..=packet.len() {
        let packet = packet[..end].to_vec();
        assert_eq!(f.call("decode_bad_before", packet.clone()).unwrap(), f.call("decode_bad_after", packet).unwrap());
    }
    for at in 0..packet.len() {
        for value in [f64::NAN, f64::INFINITY, -1., 65536., 0.5, -0.] {
            let mut packet = packet.clone();packet[at] = value;
            assert_eq!(f.call("decode_bad_before", packet.clone()).unwrap(), f.call("decode_bad_after", packet).unwrap());
        }
    }
    for count in [0u32,1,3,4,5,65,257,4096] {
        let expected: Vec<u32> = (0..count).map(|i| i.wrapping_mul(2654435761)).collect();
        assert_eq!(f.words("decode_after",count), expected);
        let expected: Vec<u32> = (0..count).map(|i| i*2).filter(|i| i%3!=0).collect();
        assert_eq!(f.words("changes_after",count), expected);
        let mut expected = vec![1,1,count+1,count,1,1,count];
        for i in 0..count {
            let tag=i%4;
            let values=match tag {0=>vec![],1=>vec![i*5,i*5+1,i*5+2],2=>vec![i*7],_=>vec![i*11]};
            expected.extend([i+1,0,1,tag,if tag==0 {0} else {1},2,1,values.len() as u32]);
            expected.extend([i,i+1,i*3]);expected.extend(values);
        }
        assert_eq!(f.words("queue_after",count), expected);
    }
    if std::env::args().any(|arg| arg=="--verify-only") { println!("Independent word witnesses and malformed decoder cases passed.");return; }
    let mut report = vec![];
    for (stem, sizes) in [("decode", [256usize,4096,65539]), ("changes",[256,4096,65536]), ("queue",[256,1024,4096])] {
        let a = format!("{stem}_before");let b = format!("{stem}_after");
        for size in sizes {
            let expected = f.call(&a,size).unwrap();
            for _ in 0..8 {assert_eq!(f.call(&a,size).unwrap(),expected);assert_eq!(f.call(&b,size).unwrap(),expected);}
            let memory_before = f.guest.memory_bytes();let mut samples = [vec![],vec![]];
            for round in 0..15 {
                for mode in if round % 2 == 0 {[0,1]} else {[1,0]} {
                    let start = Instant::now();let value = f.call(if mode==0 {&a} else {&b},size).unwrap();
                    samples[mode].push(start.elapsed().as_secs_f64()*1000.);assert_eq!(value,expected);
                }
            }
            let medians:Vec<_>=samples.iter().map(|values|{let mut v=values.clone();v.sort_by(f64::total_cmp);v[v.len()/2]}).collect();
            assert_eq!(memory_before,f.guest.memory_bytes());
            println!("{stem} {size}: {:.4} -> {:.4} ms ({:.2}x)",medians[0],medians[1],medians[0]/medians[1]);
            report.push(json!({"name":stem,"size":size,"medianMs":medians,"samplesMs":samples,"committedGuestBytes":memory_before,"replayGrowthBytes":0}));
        }
    }
    std::fs::write(".cache/next-ink-review/results.json",serde_json::to_vec_pretty(&report).unwrap()).unwrap();
}
